     "最后补了一个彩蛋：「鸡跟蛋的关系，鸡生蛋、蛋生鸡，鸡和蛋都是另外一只鸡生的，三种对吧？不对，是四种——还有一种是，家里冰箱里的那只鸡蛋和菜场里的那只鸡之间没有任何关系。」"
