     "10 年前马云在湖畔大学讲：真正厉害的领导者很会设 KPI。讲者当时觉得这有什么难的；后来自己做了要把培训与 KPI 挂钩、做技巧分析、关键任务拆解、企业核心知识管理的培训经理，才发现设 KPI 真的很难。"
