     "讲者点破：这是一个典型的压力面试题。面试官真正的关注点在于——四五年没有晋升，是你能力不行，还是你对自己没有追求？",
     "关键提醒：如果说你顺着面试官的意思去解释的话，那就把自己带到坑里面去了。因为无论是「能力不行」还是「没有追求」，都等于默认了自己的负面预设。"
