     "业主：不是，正常流程不是产证办完、双方签交接单吗？办好交接，这物业费跟我没关系吧。物业：那你今天不就是来收房了吗？你今天肯定得交点钱。",
     "业主：不嫌麻烦？那我要是现在交了，待会儿验收发现问题怎么办？物业：就是嘛，出问题你还得找开发商。你现在不交钱，待会儿出来又问我的责任。"
