     "第一性原理什么意思？查过解释后他总结：叫每一个事情都能往前倒，倒到一个唯一的原因，这个原因会决定我们这个事情的长短、结果和过程。",
     "他举了最简单的例子：你当初加入一家公司，是因为这个老板、还是因为工资、还是因为这个公司的未来加入的——这个起因和你离开的原因是一致的。又比如前两天有朋友要投资爱奇艺，他说会员不会增长了、广告投放那么多，投它干什么；朋友回答因为爱奇艺即将成为一家内容制造商。这就是他的思考。",
